using Acme.Data;
using Acme.Pricing;
using Microsoft.EntityFrameworkCore;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddDbContext<ShopDbContext>(options =>
    options.UseNpgsql(builder.Configuration.GetConnectionString("Shop")));
builder.Services.AddSingleton<PriceCache>();

var app = builder.Build();

app.MapGet("/products/{id:int}/price", async (int id, PriceCache prices, CancellationToken ct) =>
    TypedResults.Ok(await prices.GetAsync(id, ct)));

app.Run();

using System.Collections.Concurrent;
using Acme.Data;
using Microsoft.EntityFrameworkCore;

namespace Acme.Pricing;

public sealed class PriceCache(ShopDbContext db)
{
    private readonly ConcurrentDictionary<int, decimal> _prices = new();

    public async Task<decimal> GetAsync(int productId, CancellationToken ct)
    {
        if (_prices.TryGetValue(productId, out var cached)) return cached;

        var price = await db.Products
            .Where(p => p.Id == productId)
            .Select(p => p.Price)
            .SingleAsync(ct);
        _prices[productId] = price;
        return price;
    }
}

