public sealed class PriceCache(IServiceScopeFactory scopeFactory)
{
    private readonly ConcurrentDictionary<int, decimal> _prices = new();

    public async Task<decimal> GetAsync(int productId, CancellationToken ct)
    {
        if (_prices.TryGetValue(productId, out var cached)) return cached;

        await using var scope = scopeFactory.CreateAsyncScope();
        var db = scope.ServiceProvider.GetRequiredService<ShopDbContext>();
        var price = await db.Products
            .Where(p => p.Id == productId)
            .Select(p => p.Price)
            .SingleAsync(ct);
        _prices[productId] = price;
        return price;
    }
}

using Microsoft.Extensions.Caching.Memory;

public sealed class PriceCache(IServiceScopeFactory scopeFactory, IMemoryCache cache)
{
    public Task<decimal> GetAsync(int productId, CancellationToken ct) =>
        cache.GetOrCreateAsync(("price", productId), async entry =>
        {
            entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
            await using var scope = scopeFactory.CreateAsyncScope();
            var db = scope.ServiceProvider.GetRequiredService<ShopDbContext>();
            return await db.Products
                .Where(p => p.Id == productId)
                .Select(p => p.Price)
                .SingleAsync(ct);
        });

    public void Invalidate(int productId) => cache.Remove(("price", productId));
}

